def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_my, last_opp = history[-1]

    my_d = 0
    opp_d = 0
    all_my_c = True
    all_opp_c = True

    for m, o in history:
        if m == 'D':
            my_d += 1
            all_my_c = False
        if o == 'D':
            opp_d += 1
            all_opp_c = False

    if last_opp == 'C':
        if last_my == 'D':
            if my_d == 1 and all_opp_c and n >= 3:
                pm, po = history[-2]
                if pm == 'C' and po == 'C':
                    return 'C'
            return 'D'

        if all_my_c and all_opp_c and n >= 2:
            return 'D'

        if all_opp_c and my_d > 0 and n >= 3:
            pm, po = history[-2]
            if pm == 'D' and po == 'C':
                return 'D'

        return 'C'

    streak = 0
    for m, o in reversed(history):
        if o == 'D':
            streak += 1
        else:
            break

    if opp_d * 2 > n:
        return 'D'
    if streak >= 4:
        return 'D'

    if last_my == 'D':
        if n >= 2:
            pm, po = history[-2]
            if (pm == 'D' and po == 'C') or (pm == 'C' and po == 'C'):
                return 'C'
        return 'D'

    if opp_d * 2 <= n and streak <= 2:
        before = n - streak - 1
        if before >= 0:
            bm, bo = history[before]
            if bm == 'D' and bo == 'C':
                return 'C'

    return 'D'
